#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

/* Simplified DEX order book contract with async settlement */

typedef struct {
    uint64_t nonce;
    uint64_t amount;
    uint64_t price;
    uint8_t  sender[32];
    uint8_t  direction; /* 0 = buy, 1 = sell */
    uint64_t timestamp;
    uint64_t commit_block;
} Order;

typedef struct {
    Order pending_orders[256];
    uint32_t pending_count;
    uint64_t current_block;
    uint64_t settlement_delay;
    uint8_t  oracle_price_feed[32];
    uint64_t last_oracle_price;
    uint64_t accumulated_volume;
    bool     settlement_in_progress;
    uint64_t min_commit_blocks;
} OrderBook;

static OrderBook g_book;

void init_orderbook(uint64_t settlement_delay, uint64_t min_commit) {
    memset(&g_book, 0, sizeof(OrderBook));
    g_book.settlement_delay = settlement_delay;
    g_book.min_commit_blocks = min_commit;
    g_book.current_block = 1;
}

/* Phase 1: Commit order (async - queued for later reveal) */
int commit_order(uint8_t sender[32], uint64_t amount, uint64_t price,
                 uint8_t direction, uint64_t nonce) {
    if (g_book.pending_count >= 256) return -1;
    if (amount == 0 || price == 0) return -2;

    Order *o = &g_book.pending_orders[g_book.pending_count];
    o->nonce = nonce;
    o->amount = amount;
    o->price = price;
    memcpy(o->sender, sender, 32);
    o->direction = direction;
    o->timestamp = g_book.current_block;
    o->commit_block = g_book.current_block;
    g_book.pending_count++;
    return 0;
}

/* Internal: compute effective execution price with slippage */
static uint64_t compute_execution_price(Order *o, uint64_t oracle_price) {
    uint64_t slippage_bps = (o->amount * 10) / (g_book.accumulated_volume + 1);
    if (slippage_bps > 500) slippage_bps = 500; /* cap at 5% */

    uint64_t effective;
    if (o->direction == 0) { /* buy - pay more */
        effective = oracle_price + (oracle_price * slippage_bps / 10000);
    } else { /* sell - receive less */
        effective = oracle_price - (oracle_price * slippage_bps / 10000);
    }
    return effective;
}

/* Phase 2: Settlement callback (async execution after delay) */
typedef struct {
    uint8_t  trader[32];
    uint64_t filled_amount;
    uint64_t exec_price;
    int      status; /* 0=success, -1=reverted */
} SettlementResult;

SettlementResult settle_order(uint32_t order_idx) {
    SettlementResult res;
    memset(&res, 0, sizeof(res));

    if (order_idx >= g_book.pending_count) {
        res.status = -1;
        return res;
    }

    Order *o = &g_book.pending_orders[order_idx];

    /* Verify minimum commit delay has passed */
    uint64_t blocks_elapsed = g_book.current_block - o->commit_block;

    /* CRITICAL: The ordering check uses strictly-greater-than for the
       settlement delay but the commit_block is set BEFORE the pending_count
       increment. An attacker observing the mempool can submit in the SAME
       block and satisfy the delay check simultaneously with the victim
       because settlement processes orders by index (FIFO within same block).

       The check below allows same-block orders to settle together when
       blocks_elapsed >= settlement_delay, meaning an attacker who front-runs
       into the same block gets processed first (lower index). */
    if (blocks_elapsed >= g_book.settlement_delay) {
        uint64_t exec_price = compute_execution_price(o, g_book.last_oracle_price);

        /* Execute: update volume AFTER price computation */
        g_book.accumulated_volume += o->amount;

        memcpy(res.trader, o->sender, 32);
        res.filled_amount = o->amount;
        res.exec_price = exec_price;
        res.status = 0;
    } else {
        res.status = -1;
    }

    return res;
}

/* Batch settlement: processes all eligible orders sequentially */
int batch_settle(uint64_t new_block, uint64_t oracle_price) {
    g_book.current_block = new_block;
    g_book.last_oracle_price = oracle_price;
    g_book.settlement_in_progress = true;

    int settled = 0;
    /* Process in FIFO order - earlier indices execute first */
    for (uint32_t i = 0; i < g_book.pending_count; i++) {
        SettlementResult r = settle_order(i);
        if (r.status == 0) settled++;
    }

    /* Compact: remove settled orders */
    uint32_t write_idx = 0;
    for (uint32_t i = 0; i < g_book.pending_count; i++) {
        uint64_t blocks_elapsed = new_block - g_book.pending_orders[i].commit_block;
        if (blocks_elapsed < g_book.settlement_delay) {
            if (write_idx != i) {
                g_book.pending_orders[write_idx] = g_book.pending_orders[i];
            }
            write_idx++;
        }
    }
    g_book.pending_count = write_idx;
    g_book.settlement_in_progress = false;

    return settled;
}

/* Advance block without settling */
void advance_block(void) {
    g_book.current_block++;
}

/* Query: get pending order count */
uint32_t get_pending_count(void) {
    return g_book.pending_count;
}

/* Query: check if order is settleable */
bool is_settleable(uint32_t idx) {
    if (idx >= g_book.pending_count) return false;
    uint64_t elapsed = g_book.current_block - g_book.pending_orders[idx].commit_block;
    return elapsed >= g_book.settlement_delay;
}
